    alternatives: live.filter((x, i, arr) => x !== bestTrade && x.setup !== plan.setup && arr.findIndex((y) => y.setup.dir === x.setup.dir && y.setup.tf === x.setup.tf && y.setup.state === x.setup.state) === i).slice(0, 4).map((x) => ({
