:root {
  --bg: #0b0e13; --panel: #131821; --panel2: #1a2030; --line: #252c3b; --text: #e6e9ef; --muted: #8b94a7;
  --bull: #26a69a; --bear: #ef5350; --amber: #f0b429; --blue: #5b9cf5; --violet: #a78bfa;
  --radius: 10px; --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body { margin: 0; background: var(--bg); color: var(--text); font: 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
h1, h2, h3, p { margin: 0; }
button, select, input { font: inherit; color: inherit; }

.top { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; justify-content: space-between; padding: 14px 20px; border-bottom: 1px solid var(--line); background: var(--panel); position: sticky; top: 0; z-index: 5; }
.brand { display: flex; gap: 12px; align-items: center; }
.brand h1 { font-size: 17px; letter-spacing: .2px; }
.brand p { color: var(--muted); font-size: 12px; }
.logo { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 9px; background: linear-gradient(135deg, var(--blue), var(--violet)); font-weight: 800; font-size: 13px; color: #0b0e13; }
.controls { display: flex; flex-wrap: wrap; gap: 10px 14px; align-items: center; }
.seg { display: inline-flex; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 3px; }
.seg button { border: 0; background: none; padding: 6px 12px; border-radius: 6px; cursor: pointer; color: var(--muted); font-weight: 600; }
.seg button.on { background: var(--panel2); color: var(--text); box-shadow: inset 0 0 0 1px var(--line); }
.field { display: flex; gap: 8px; align-items: center; color: var(--muted); font-size: 12px; }
select, .filebtn { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 7px 10px; color: var(--text); }
.filebtn { cursor: pointer; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.filebtn input { display: none; }
.primary { background: var(--blue); color: #08101f; border: 0; border-radius: 8px; padding: 8px 18px; font-weight: 700; cursor: pointer; }
.primary:disabled { opacity: .55; cursor: progress; }
.check { display: flex; gap: 6px; align-items: center; color: var(--muted); font-size: 12px; cursor: pointer; }

.banner { margin: 14px 20px 0; padding: 10px 14px; border-radius: 8px; border: 1px solid var(--line); background: var(--panel); color: var(--muted); }
.banner.warn { border-color: #6b5312; background: #241d08; color: #f3d37a; }
.banner.err { border-color: #6b1f1f; background: #260f0f; color: #f6a5a5; }

main { padding: 14px 20px 30px; display: grid; gap: 14px; max-width: 1700px; margin: 0 auto; }
.grid { display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 14px; align-items: start; }
.grid2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; align-items: start; }
.side { display: grid; gap: 14px; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; min-width: 0; }
.panel h2 { font-size: 13px; text-transform: uppercase; letter-spacing: .8px; color: var(--muted); margin-bottom: 12px; }
.panel h2 small { text-transform: none; letter-spacing: 0; font-weight: 400; margin-left: 6px; }

.chartPanel { padding: 10px; }
.chartBar { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; justify-content: space-between; padding: 2px 4px 10px; }
.layers { display: flex; flex-wrap: wrap; gap: 6px; }
.layers button { border: 1px solid var(--line); background: none; color: var(--muted); border-radius: 999px; padding: 3px 10px; font-size: 12px; cursor: pointer; }
.layers button.on { color: var(--text); background: var(--panel2); border-color: #3a4560; }
.chartWrap { position: relative; height: 560px; }
#chart { width: 100%; height: 100%; display: block; cursor: crosshair; border-radius: 6px; touch-action: none; }
.tip { position: absolute; top: 8px; left: 10px; font: 12px var(--mono); color: var(--muted); background: rgba(11, 14, 19, .8); padding: 3px 8px; border-radius: 6px; pointer-events: none; }
.legend { display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 10px 4px 2px; color: var(--muted); font-size: 12px; }
.sw { display: inline-block; width: 14px; height: 10px; border-radius: 2px; margin-right: 6px; vertical-align: -1px; }
.sw.bullZ { background: rgba(38, 166, 154, .35); border: 1px solid var(--bull); }
.sw.bearZ { background: rgba(239, 83, 80, .3); border: 1px solid var(--bear); }
.sw.obB { background: rgba(91, 156, 245, .25); border: 1px solid var(--blue); }
.sw.liq { background: none; border-top: 2px dashed var(--amber); height: 0; vertical-align: 3px; }
.sw.kz { background: rgba(167, 139, 250, .22); }

.verdict .head { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
.badge { font-size: 22px; font-weight: 800; letter-spacing: 1px; padding: 6px 16px; border-radius: 8px; }
.badge.LONG { background: rgba(38, 166, 154, .18); color: var(--bull); border: 1px solid var(--bull); }
.badge.SHORT { background: rgba(239, 83, 80, .16); color: var(--bear); border: 1px solid var(--bear); }
.badge.WAIT { background: rgba(240, 180, 41, .14); color: var(--amber); border: 1px solid var(--amber); }
.verdict .sub { color: var(--muted); font-size: 12px; }
.verdict .sub b { color: var(--text); font-size: 15px; }
.meter { height: 8px; border-radius: 99px; background: var(--bg); overflow: hidden; display: flex; margin: 10px 0 4px; }
.meter i { display: block; height: 100%; }
.meter .ict { background: var(--blue); } .meter .news { background: var(--violet); }
.meterLbl { display: flex; justify-content: space-between; font-size: 11px; color: var(--muted); margin-bottom: 10px; }
.why { background: var(--panel2); border-radius: 8px; padding: 9px 11px; font-size: 13px; margin: 8px 0; }
.lv { width: 100%; border-collapse: collapse; font-family: var(--mono); font-size: 13px; margin-top: 6px; }
.lv td { padding: 6px 4px; border-top: 1px solid var(--line); }
.lv td:first-child { font-family: system-ui, sans-serif; color: var(--muted); }
.lv td:nth-child(2) { text-align: right; font-weight: 700; }
.lv td:nth-child(3) { text-align: right; color: var(--muted); font-size: 12px; }
.lv tr.entry td:nth-child(2) { color: var(--text); } .lv tr.stop td:nth-child(2) { color: var(--bear); } .lv tr.tp td:nth-child(2) { color: var(--bull); }
.lv tr.pref td:first-child::after { content: " ★"; color: var(--amber); }
.note { color: var(--muted); font-size: 12px; margin-top: 8px; }
.ref { opacity: .75; }
.tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.tag { font-size: 11px; padding: 2px 8px; border-radius: 99px; background: var(--panel2); color: var(--muted); border: 1px solid var(--line); }

.sz { display: grid; grid-template-columns: 1fr auto; gap: 8px 10px; align-items: center; }
.sz input { width: 110px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 6px 8px; text-align: right; font-family: var(--mono); }
.sz .big { font: 700 20px var(--mono); }
.sz .k { color: var(--muted); }

